const u = $input.first().json;
const m = u.message || null;
const cb = u.callback_query || null;
const src = cb ? cb.message : m;
const from = cb ? cb.from : (m ? m.from : {});
const photo = m && m.photo ? m.photo[m.photo.length - 1] : null; // largest size
const isImg = d => d && /^image\/(jpeg|png|webp)$/.test(d.mime_type || '');
const doc = m && isImg(m.document) ? m.document : null;
const text = m && m.text ? m.text.trim() : '';
return [{ json: {
 update_id: u.update_id,
 chat_id: src ? src.chat.id : null,
 user_id: from.id,
 who: from.first_name || from.username || String(from.id),
 message_id: src ? src.message_id : null,
 text,
 caption: m && m.caption ? m.caption.trim() : '',
 file_id: photo ? photo.file_id : (doc ? doc.file_id : null),
 mime: doc ? doc.mime_type : 'image/jpeg',
 callback_id: cb ? cb.id : null,
 callback_data: cb ? cb.data : null,
 kind: cb ? 'callback' : (photo || doc) ? 'image' : text.startsWith('/') ? 'command' : text ? 'text' : 'other'
} }];

const n = $input.first().json;
const arg = n.callback_data ? (n.txn_id || '') : (n.text.split(/\s+/)[1] || '');
return [{ json: { ...n, txn_id: String(arg).toUpperCase() } }];

const n = $('Undo Parse').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.txn_id && r.status === 'ok');
let row;
if (n.txn_id) row = rows.find(r => r.txn_id === n.txn_id);
else row = rows.filter(r => r.who === n.who)
 .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)))[0];
return [{ json: { ...n, found: !!row, target: row || null } }];

// "/edit K3F9A kategori=Transport nominal=50000 catatan=parkir bandara"
const n = $input.first().json;
const t = n.text.replace(/^\/edit(@\w+)?\s*/i, '');
const id = (t.match(/^(\w{5})\b/) || [])[1];
const get = k => {
 const m = t.match(new RegExp(k + '=([^=]+?)(?=\\s+\\w+=|$)', 'i'));
 return m ? m[1].trim() : undefined;
};
const nom = get('nominal');
return [{ json: { ...n, txn_id: id && id.toUpperCase(), category: get('kategori'),
 amount: nom ? parseInt(nom.replace(/\D/g, ''), 10) : undefined, notes: get('catatan') } }];

const n = $('Edit Parse').first().json;
const cats = $('Config').first().json.categories;
if (!n.txn_id) {
 return [{ json: { ...n, ok: false, msg: 'Format: /edit ID kategori=... nominal=... catatan=...' } }];
}
const rows = $input.all().map(i => i.json);
const row = rows.find(r => r.txn_id === n.txn_id && r.status === 'ok');
if (!row) return [{ json: { ...n, ok: false, msg: 'ID tidak ditemukan atau sudah dibatalkan.' } }];
let cat = row.category;
if (n.category) {
 const hit = cats.find(c => c.toLowerCase() === n.category.toLowerCase());
 if (!hit) return [{ json: { ...n, ok: false, msg: 'Kategori tidak dikenal. Pilihan: ' + cats.join(', ') } }];
 cat = hit;
}
const amount = n.amount && n.amount > 0 ? n.amount : Number(row.amount);
const notes = n.notes !== undefined ? n.notes : (row.notes || '');
return [{ json: { ...n, ok: true, new_category: cat, new_amount: amount, new_notes: notes } }];

const n = $('Normalize').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.txn_id && r.status === 'ok');
rows.sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
const lines = rows.slice(0, 10).map(r =>
 `${r.txn_id} | ${r.txn_date} | Rp ${Number(r.amount).toLocaleString('id-ID')} | ${r.category}`
 + ` | ${r.merchant} | ${r.who}`);
return [{ json: { chat_id: n.chat_id, text: lines.length ? lines.join('\n') : 'Belum ada transaksi.' } }];

const n = $input.first().json;
const [op, id, arg] = String(n.callback_data || '').split('|');
return [{ json: { ...n, op, txn_id: id, arg } }];

const n = $('Parse Callback').first().json;
const cats = $('Config').first().json.categories;
const cat = cats[Number(n.arg)];
const row = $input.all().map(i => i.json).find(r => r.txn_id === n.txn_id && r.status === 'ok');
return [{ json: { ...n, ok: !!(row && cat), new_category: cat } }];

const n = $('Parse Callback').first().json;
const row = $input.all().map(i => i.json).find(r => r.conf_id);
if (!row) return [{ json: { ...n, found: false } }];
const p = JSON.parse(row.payload);
return [{ json: { ...p, confirmed: true, found: true, cb_chat_id: n.chat_id,
cb_message_id: n.message_id, conf_row_id: row.id } }];
